# Expected values generated by test/torch/gen_nn_expected.py (torch 2.15.0).
import torch
import torch.nn as nn
import torch.nn.functional as F

def X(shape: List[int], seed: int, dtype = torch.float64) -> torch.Tensor:
    n = 1
    for s in shape: n *= s
    return ((torch.arange(n, dtype=torch.float64) * 0.37 + float(seed)).sin() * 2.0).reshape(shape).to(dtype)

def close(t: torch.Tensor, exp: List[float], rtol: float) -> bool:
    v = t.detach().contiguous().reshape([-1]).double().tolist()
    if len(v) != len(exp):
        print("len mismatch", len(v), len(exp))
        return False
    scale = 0.0
    for e in exp: scale = max(scale, abs(e))
    for i in range(len(v)):
        if abs(v[i] - exp[i]) > rtol * max(abs(exp[i]), 1e-3 * scale):
            print("mismatch at", i, v[i], exp[i])
            return False
    return True

def closef(a: float, b: float, rtol: float) -> bool:
    return abs(a - b) <= rtol * abs(b)
from torch.utils.data import TensorDataset, DataLoader, random_split, Subset, ConcatDataset

@test
def test_dataloader():
    torch.manual_seed(5)
    ds = TensorDataset(torch.arange(10, dtype=torch.float32).reshape([10, 1]), torch.arange(10))
    assert len(ds) == 10
    dl = DataLoader(ds, batch_size=4, shuffle=True)
    assert len(dl) == 3
    order = List[int]()
    for ep in range(2):
        for xb, yb in dl:
            assert xb.shape[1] == 1
            for i in range(yb.numel()):
                order.append(int(yb[i].item()))
    assert order == [8, 3, 0, 5, 9, 1, 6, 2, 4, 7, 5, 8, 9, 7, 2, 0, 4, 1, 3, 6]  # dl_order
    g = torch.Generator().manual_seed(7)
    dl2 = DataLoader(ds, batch_size=3, shuffle=True, generator=g, drop_last=True)
    order = []
    for xb, yb in dl2:
        for i in range(yb.numel()):
            order.append(int(yb[i].item()))
    assert order == [1, 3, 5, 7, 9, 4, 6, 2, 8]  # dl_gen_order
    assert close(torch.rand([2]), [0.0332646369934082, 0.9941847324371338], 0.0)  # after_dl

@test
def test_split_subset_concat():
    ds = TensorDataset(torch.arange(10, dtype=torch.float32).reshape([10, 1]), torch.arange(10))
    parts = random_split(ds, [0.7, 0.3], generator=torch.Generator().manual_seed(42))
    assert parts[0].indices + parts[1].indices == [2, 6, 1, 8, 4, 5, 0, 9, 3, 7]  # split_idx
    s = Subset(ds, [3, 1])
    assert len(s) == 2 and int(s[0][1].item()) == 3
    c = ConcatDataset([s, s])
    assert len(c) == 4 and int(c[3][1].item()) == 1
    dl = DataLoader(ds, batch_size=4)
    sizes = [int(xb.shape[0]) for xb, yb in dl]
    assert sizes == [4, 4, 2]

test_dataloader()
test_split_subset_concat()
